        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead coupling: If next_item_size is large, prefer bins that can fit it.
    // If post_residual is too small to fit next_item_size, we apply a penalty.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower open_bins_count)
    // to avoid fragmentation, but keep the residual balanced.
    let density_penalty = (open_bins_count as f64 - (100.0 - mean_residual) / 100.0) * 5.0;
    score += density_penalty * progress;

    // If this is the last chance for the current item, lower the score to force acceptance
    // and avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // If evaluating a new bin (bin_residual == bin_capacity), apply a high base cost
    // to discourage opening new bins unless the fit in existing ones is terrible.
    if bin_residual == bin_capacity {
        score = 45.0 + (progress * 15.0);
    }

    score
}

