pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We prioritize bins that leave very little space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If the next item can fit perfectly or near-perfectly
    // into the current post_residual, drastically reduce the score.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item
            score -= (100.0 - (post_residual - next_item_size) as f64).powf(1.2);
        } else {
            // Penalize bins that leave a gap too small for the next item
            score += 50.0;
        }
    }

    // 3. Global Efficiency: Balance the number of open bins.
    // If few bins are open, we are more conservative.
    score += (open_bins_count as f64) * 5.0;

    // 4. Mean Residual Correction: Avoid bins that deviate significantly 
    // from the current average residual (encouraging uniform filling).
    score += ((post_residual as f64 - mean_residual).abs()) * 2.0;

    // 5. New Bin Logic: If this is an empty bin, apply a threshold.
    // Only choose a new bin if the current "best" fit is extremely poor (post_residual is large).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already high 
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count == 0 {
            score = 0.0;
        } else {
            // Apply a heavy premium to opening new bins when space exists.
            score = 150.0 + (mean_residual * 2.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
