        score -= 50.0;
    }

    // 5. Global efficiency: Discourage opening a new bin (bin_residual == bin_capacity)
    // unless the mean residual is already quite high (meaning we have "bad" bins already).
    if bin_residual == bin_capacity {
        score += 35.0 + (mean_residual * 0.5);
    }

    // 6. Balance against mean: Penalize bins that deviate negatively from the mean residual,
    // as they are likely to become stranded.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    score
