    // We aim to minimize the post_residual, but heavily penalize small, unusable "sliver" residuals
    // that cannot accommodate typical future items.

    let post = post_residual as f64;
    let capacity = bin_capacity as f64;
    let mut score = post;

    // 1. Harmonic Penalty: If post_residual is small but > 0, it's often a "dead" zone.
    // We penalize residuals that are smaller than the smallest likely items (e.g., < 10).
    if post > 0.0 && post < 10.0 {
