    // If post_residual is smaller than the next_item_size, we penalize this bin to keep it for smaller items.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 20.0;
        } else {
            // Reward bins that are "perfect matches" for the lookahead
            score -= (post - next_item_size as f64) * 0.1;
        }
