    // 3. Open Bin Pressure: As the stream progresses, favor packing tighter (lower mean_residual).
    // If we have many open bins, prioritize clearing those with high residuals.
    let progress = step_index as f64 / total_items as f64;
    if open_bins_count > 0 {
        score += (mean_residual - post) * progress;
    }

    // 4. New Bin Logic:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only open a new bin if the penalty for fitting into existing bins is too high.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, reduced by total open bins to avoid fragmentation.
        score += 45.0 - (open_bins_count as f64 * 0.5);
    } else {
        // If it's a fitting bin, prioritize based on how well it fits (Best Fit variant)
        // We subtract a small bonus for bins that are nearly filled.
        score -= (capacity - post) * 0.01;
